try:
    import unittest2 as unittest
except ImportError:
    import unittest  # type: ignore

from taf.cloud.cbam.schemas.vnf_info import VnfInfo, VnfInfoLinks


class TestVnfInfoLinks(unittest.TestCase):

    def test_CreateObject(self):
        params = ['param0', 'param1', 'param2', 'param3', 'param4', 'param5', 'param6', 'param7', 'param8',
                  'param9', 'param10', 'param11']
        links_object = VnfInfoLinks(self_link=params[0], operation_executions=params[1], extensions=params[2],
                                    vnf_configurable_properties=params[3], instantiated_vnf_info=params[4],
                                    modify_info=params[5], heal=params[6], scale=params[7],
                                    terminate=params[8], list_link=params[9], delete=params[10],
                                    instantiate=params[11])
        self.assertEqual(links_object.self_link, params[0])
        self.assertEqual(links_object.operation_executions, params[1])
        self.assertEqual(links_object.extensions, params[2])
        self.assertEqual(links_object.vnf_configurable_properties, params[3])
        self.assertEqual(links_object.instantiated_vnf_info, params[4])
        self.assertEqual(links_object.modify_info, params[5])
        self.assertEqual(links_object.heal, params[6])
        self.assertEqual(links_object.scale, params[7])
        self.assertEqual(links_object.terminate, params[8])
        self.assertEqual(links_object.list_link, params[9])
        self.assertEqual(links_object.delete, params[10])
        self.assertEqual(links_object.instantiate, params[11])

    def test_createObjectFromResponseDict(self):
        response = {'self': {'href': 'param0'}, 'operationExecutions': {'href': 'param1'},
                    'extensions': {'href': 'param2'}, 'vnfConfigurableProperties': {'href': 'param3'},
                    'instantiatedVnfInfo': {'href': 'param4'}, 'modifyInfo': {'href': 'param5'},
                    'heal': {'href': 'param6'}, 'scale': {'href': 'param7'}, 'terminate': {'href': 'param8'},
                    'list': {'href': 'param9'}, 'delete': {'href': 'param10'}, 'instantiate': {'href': 'param11'}}
        links_object = VnfInfoLinks.from_response_dict(response_dict=response)
        self.assertEqual(links_object.self_link, response['self']['href'])
        self.assertEqual(links_object.operation_executions, response['operationExecutions']['href'])
        self.assertEqual(links_object.extensions, response['extensions']['href'])
        self.assertEqual(links_object.vnf_configurable_properties, response['vnfConfigurableProperties']['href'])
        self.assertEqual(links_object.instantiated_vnf_info, response['instantiatedVnfInfo']['href'])
        self.assertEqual(links_object.modify_info, response['modifyInfo']['href'])
        self.assertEqual(links_object.heal, response['heal']['href'])
        self.assertEqual(links_object.scale, response['scale']['href'])
        self.assertEqual(links_object.terminate, response['terminate']['href'])
        self.assertEqual(links_object.list_link, response['list']['href'])
        self.assertEqual(links_object.delete, response['delete']['href'])
        self.assertEqual(links_object.instantiate, response['instantiate']['href'])

    def test_returnObject_asDict(self):
        response = {'self': {'href': 'param0'}, 'operationExecutions': {'href': 'param1'},
                    'extensions': {'href': 'param2'}, 'vnfConfigurableProperties': {'href': 'param3'},
                    'instantiatedVnfInfo': {'href': 'param4'}, 'modifyInfo': {'href': 'param5'},
                    'heal': {'href': 'param6'}, 'scale': {'href': 'param7'}, 'terminate': {'href': 'param8'},
                    'list': {'href': 'param9'}, 'delete': {'href': 'param10'}, 'instantiate': {'href': 'param11'}}
        links_object = VnfInfoLinks.from_response_dict(response_dict=response)
        links_dict = links_object.as_dict()
        self.assertEqual(links_dict['self'], response['self'])
        self.assertEqual(links_dict['operationExecutions'], response['operationExecutions'])
        self.assertEqual(links_dict['extensions'], response['extensions'])
        self.assertEqual(links_dict['vnfConfigurableProperties'], response['vnfConfigurableProperties'])
        self.assertEqual(links_dict['instantiatedVnfInfo'], response['instantiatedVnfInfo'])
        self.assertEqual(links_dict['modifyInfo'], response['modifyInfo'])
        self.assertEqual(links_dict['heal'], response['heal'])
        self.assertEqual(links_dict['scale'], response['scale'])
        self.assertEqual(links_dict['terminate'], response['terminate'])
        self.assertEqual(links_dict['list'], response['list'])
        self.assertEqual(links_dict['delete'], response['delete'])
        self.assertEqual(links_dict['instantiate'], response['instantiate'])


class TestVnfInfo(unittest.TestCase):
    def test_createObject(self):
        params = {'id': 'id', 'vnfdId': 'vnfdId', 'vnfSoftwareVersion': 'vnfSoftwareVersion',
                  'vnfdVersion': 'vnfdVersion', 'onboardedVnfPkgInfoId': 'onboardedVnfPkgInfoId',
                  'instantiationState': 'instantiationState', 'name': 'name', 'description': 'description',
                  'vnf_provider': 'vnf_provider', 'vnf_product_name': 'vnf_product_name',
                  'operation_executions': 'operation_executions', 'instantiated_vnf_info': 'instantiated_vnf_info',
                  'vnf_configurable_properties': 'vnf_configurable_properties', 'extensions': 'extensions',
                  'metadata': 'metadata', 'links': 'links'}
        vnf_object = VnfInfo(id=params['id'], vnfd_id=params['vnfdId'],
                             vnf_software_version=params['vnfSoftwareVersion'], vnfd_version=params['vnfdVersion'],
                             on_boarded_vnf_pkg_info_id=params['onboardedVnfPkgInfoId'],
                             instantiation_state=params['instantiationState'], name=params['name'],
                             description=params['description'], vnf_provider=params['vnf_provider'],
                             vnf_product_name=params['vnf_product_name'],
                             operation_executions=params['operation_executions'],
                             instantiated_vnf_info=params['instantiated_vnf_info'],
                             vnf_configurable_properties=params['vnf_configurable_properties'],
                             extensions=params['extensions'], metadata=params['metadata'], links=params['links'])
        self.assertEqual(vnf_object.id, params['id'])
        self.assertEqual(vnf_object.vnfd_id, params['vnfdId'])
        self.assertEqual(vnf_object.vnf_software_version, params['vnfSoftwareVersion'])
        self.assertEqual(vnf_object.vnfd_version, params['vnfdVersion'])
        self.assertEqual(vnf_object.on_boarded_vnf_pkg_info_id, params['onboardedVnfPkgInfoId'])
        self.assertEqual(vnf_object.instantiation_state, params['instantiationState'])
        self.assertEqual(vnf_object.name, params['name'])
        self.assertEqual(vnf_object.description, params['description'])
        self.assertEqual(vnf_object.vnf_provider, params['vnf_provider'])
        self.assertEqual(vnf_object.vnf_product_name, params['vnf_product_name'])
        self.assertEqual(vnf_object.operation_executions, params['operation_executions'])
        self.assertEqual(vnf_object.instantiated_vnf_info, params['instantiated_vnf_info'])
        self.assertEqual(vnf_object.vnf_configurable_properties, params['vnf_configurable_properties'])
        self.assertEqual(vnf_object.extensions, params['extensions'])
        self.assertEqual(vnf_object.metadata, params['metadata'])
        self.assertEqual(vnf_object.links, params['links'])

    def test_createObject_FromResponseDict(self):
        response = {'id': 'id', 'vnfdId': 'vnfdId', 'vnfSoftwareVersion': 'vnfSoftwareVersion',
                    'vnfdVersion': 'vnfdVersion', 'onboardedVnfPkgInfoId': 'onboardedVnfPkgInfoId',
                    'instantiationState': 'instantiationState', 'name': 'name', 'description': 'description',
                    'vnfProvider': 'vnfProvider', 'vnfProductName': 'vnfProductName',
                    'operationExecutions': [
                        {'id': 'id', 'vnfInstanceId': 'vnfInstanceId',
                         'operationType': 'operationType', 'status': 'status',
                         'isCancelPending': 'isCancelPending', 'startTime': 'startTime'}],
                    'instantiatedVnfInfo': 'instantiatedVnfInfo',
                    'vnfConfigurableProperties': 'vnfConfigurableProperties', 'extensions': 'extensions',
                    'metadata': 'metadata', '_links': {'self': {'href': 'self_link'}}}
        vnf_info_object = VnfInfo.from_response_dict(response_dict=response)
        self.assertEqual(vnf_info_object.id, response['id'])
        self.assertEqual(vnf_info_object.vnfd_id, response['vnfdId'])
        self.assertEqual(vnf_info_object.vnf_software_version, response['vnfSoftwareVersion'])
        self.assertEqual(vnf_info_object.vnfd_version, response['vnfdVersion'])
        self.assertEqual(vnf_info_object.on_boarded_vnf_pkg_info_id, response['onboardedVnfPkgInfoId'])
        self.assertEqual(vnf_info_object.instantiation_state, response['instantiationState'])
        self.assertEqual(vnf_info_object.name, response['name'])
        self.assertEqual(vnf_info_object.description, response['description'])
        self.assertEqual(vnf_info_object.vnf_provider, response['vnfProvider'])
        self.assertEqual(vnf_info_object.vnf_product_name, response['vnfProductName'])
        self.assertDictEqual(vnf_info_object.operation_executions[0].as_dict(), response['operationExecutions'][0])
        self.assertEqual(vnf_info_object.instantiated_vnf_info, response['instantiatedVnfInfo'])
        self.assertEqual(vnf_info_object.vnf_configurable_properties, response['vnfConfigurableProperties'])
        self.assertEqual(vnf_info_object.extensions, response['extensions'])
        self.assertEqual(vnf_info_object.metadata, response['metadata'])
        self.assertDictEqual(vnf_info_object.links.as_dict(), response['_links'])

    def test_returnObject_asDict(self):
        response = {'id': 'id', 'vnfdId': 'vnfdId', 'vnfSoftwareVersion': 'vnfSoftwareVersion',
                    'vnfdVersion': 'vnfdVersion', 'onboardedVnfPkgInfoId': 'onboardedVnfPkgInfoId',
                    'instantiationState': 'instantiationState', 'name': 'name', 'description': 'description',
                    'vnfProvider': 'vnfProvider', 'vnfProductName': 'vnfProductName',
                    'operationExecutions': [
                        {'id': 'id', 'vnfInstanceId': 'vnfInstanceId',
                         'operationType': 'operationType', 'status': 'status',
                         'isCancelPending': 'isCancelPending', 'startTime': 'startTime'}],
                    'instantiatedVnfInfo': 'instantiatedVnfInfo',
                    'vnfConfigurableProperties': 'vnfConfigurableProperties', 'extensions': 'extensions',
                    'metadata': 'metadata', '_links': {'self': {'href': 'self_link'}}}
        vnf_info_object = VnfInfo.from_response_dict(response_dict=response)
        vnf_info_dict = vnf_info_object.as_dict()
        self.assertEqual(vnf_info_dict['id'], response['id'])
        self.assertEqual(vnf_info_dict['vnfdId'], response['vnfdId'])
        self.assertEqual(vnf_info_dict['vnfSoftwareVersion'], response['vnfSoftwareVersion'])
        self.assertEqual(vnf_info_dict['vnfdVersion'], response['vnfdVersion'])
        self.assertEqual(vnf_info_dict['onboardedVnfPkgInfoId'], response['onboardedVnfPkgInfoId'])
        self.assertEqual(vnf_info_dict['instantiationState'], response['instantiationState'])
        self.assertEqual(vnf_info_dict['name'], response['name'])
        self.assertEqual(vnf_info_dict['description'], response['description'])
        self.assertEqual(vnf_info_dict['vnfProvider'], response['vnfProvider'])
        self.assertEqual(vnf_info_dict['vnfProductName'], response['vnfProductName'])
        self.assertDictEqual(vnf_info_dict['operationExecutions'][0], response['operationExecutions'][0])
        self.assertEqual(vnf_info_dict['instantiatedVnfInfo'], response['instantiatedVnfInfo'])
        self.assertEqual(vnf_info_dict['vnfConfigurableProperties'], response['vnfConfigurableProperties'])
        self.assertEqual(vnf_info_dict['extensions'], response['extensions'])
        self.assertEqual(vnf_info_dict['metadata'], response['metadata'])
        self.assertDictEqual(vnf_info_dict['_links'], response['_links'])
